func Test_OptionsWhitespaceStrict(t *testing.T) {
	// Strict whitespace mode preserves whitespace as-is
	var options htmd.ConversionOptions
	if err := json.Unmarshal([]byte(`{"whitespace_mode":"strict"}`), &options); err != nil {
		t.Fatalf("config parse failed: %v", err)
	}
	result, err := htmd.Convert(`<p>Preserved   spacing.</p>`, &options)
	if err != nil {
		t.Fatalf("call failed: %v", err)
	}
	if result.Content == nil {
		t.Errorf("expected non-empty value")
	}
	if result.Content == nil || !strings.Contains(string(*result.Content), `Preserved`) {
		t.Errorf("expected to contain %s", `Preserved`)
	}
	if result.Content == nil || !strings.Contains(string(*result.Content), `spacing.`) {
		t.Errorf("expected to contain %s", `spacing.`)
	}
}

func Test_OptionsWrapDisabled(t *testing.T) {
	// Wrap option disabled preserves long lines without breaking
	var options htmd.ConversionOptions
	if err := json.Unmarshal([]byte(`{"wrap":false}`), &options); err != nil {
		t.Fatalf("config parse failed: %v", err)
	}
	result, err := htmd.Convert(`<p>This is a long paragraph that should not be wrapped at all because wrapping is disabled.</p>`, &options)
	if err != nil {
		t.Fatalf("call failed: %v", err)
	}
	if result.Content == nil || !strings.Contains(string(*result.Content), `This is a long paragraph that should not be wrapped at all because wrapping is disabled.`) {
		t.Errorf("expected to contain %s", `This is a long paragraph that should not be wrapped at all because wrapping is disabled.`)
	}
}

func Test_OptionsWrapEnabled(t *testing.T) {
	// Wrap option enabled with custom width wraps long lines
	var options htmd.ConversionOptions
	if err := json.Unmarshal([]byte(`{"wrap":true,"wrap_width":40}`), &options); err != nil {
		t.Fatalf("config parse failed: %v", err)
	}
	result, err := htmd.Convert(`<p>This is a long paragraph that should be wrapped at the specified column width when the wrap option is enabled.</p>`, &options)
	if err != nil {
		t.Fatalf("call failed: %v", err)
	}
	if result.Content == nil {
		t.Errorf("expected non-empty value")
	}
	if result.Content == nil || !strings.Contains(string(*result.Content), `This is a long paragraph`) {
		t.Errorf("expected to contain %s", `This is a long paragraph`)
	}
}
